int fd = open("/var/log", O_RDONLY | O_DIRECTORY);

if (fd < 0) {
    /* Handle open failure */
    return -1;
}

// Attempt to change the CWD using the directory file descriptor
if (fchdir(fd) == -1) {
    /* EACCES: Denied search permission
       EBADF: fd is not valid
       ENOTDIR: fd refers to a file */
    perror("fchdir");
}

close(fd);
